const search=document.getElementById('search'),filter=document.getElementById('filter');function apply(){let n=0;document.querySelectorAll('tbody tr').forEach(r=>{let ok=r.textContent.includes(search.value.trim())&&(filter.value==='all'||filter.value==='corrected'&&r.dataset.corrected==='1'||filter.value==='red'&&r.classList.contains('red')||filter.value==='missing'&&r.dataset.missing==='1');r.hidden=!ok;if(ok)n++});document.getElementById('count').textContent=n+' موضع'}search.addEventListener('input',apply);filter.addEventListener('change',apply);apply();
</script></body></html>
